import React from "react";
import { useNavigate } from "react-router-dom";
import "./Questionnaire.css";

function Questionnaire({ onNext }) {
  const navigate = useNavigate();

  const handleContinue = () => {
    if (typeof onNext === "function") {
      onNext(); // keeps your original behavior
    }
    navigate("/spending-priority");
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">

        {/* ✅ KEEP YOUR ORIGINAL TITLE */}
        <h2 className="questionnaire-title">Financial Questionnaire</h2>

        {/* ✅ PASTE YOUR ORIGINAL QUESTIONS EXACTLY BELOW */}
        {/* ❗ Do NOT change class names */}
        {/* ❗ Do NOT change labels */}
        {/* ❗ Do NOT change options */}

        {/* ===== PASTE YOUR EXISTING FORM GROUPS HERE ===== */}



        {/* ===== END OF YOUR ORIGINAL QUESTIONS ===== */}

        <button className="next-button" onClick={handleContinue}>
          Continue
        </button>

      </div>
    </div>
  );
}

export default Questionnaire;
